import warnings
import numpy as np

import statsmodels.tsa.statespace.dynamic_factor_mq as mod
from statsmodels.tools.sm_exceptions import ConvergenceWarning, EstimationWarning


def _record_basic(name, res):
    # Record mle_retvals keys and converged attribute if present
    try:
        rr = res.mle_retvals
        try:
            keys = sorted(list(getattr(rr, 'keys', lambda: [])()))
        except Exception:
            # Bunch doesn't always expose keys() as method; fall back
            try:
                keys = sorted(list(rr.__dict__.keys()))
            except Exception:
                keys = None
        probe(name + '::mle_retvals_type', type(rr).__name__)
        probe(name + '::mle_retvals_keys', keys)
        try:
            conv = rr.converged
            probe(name + '::converged', conv)
            probe(name + '::converged_dtype', type(conv).__name__)
            probe(name + '::converged_repr', repr(conv))
        except Exception as e:
            probe(name + '::converged_error', '__error__: ' + type(e).__name__ + ': ' + str(e))
    except Exception as e:
        probe(name + '::res_mle_retvals_error', '__error__: ' + type(e).__name__ + ': ' + str(e))


def _get_small_em_model():
    # Use module helper assumed by the report description.
    # If not available, create a minimal DynamicFactorMQ instance.
    try:
        return mod._get_small_em_model()
    except AttributeError:
        # Fallback minimal construction
        # DynamicFactorMQ requires endog; use a small random dataset.
        endog = np.arange(20, dtype=float).reshape(10, 2)
        # 1 factor, 1 lag, 0 irregular? keep defaults as robust as possible
        model = mod.DynamicFactorMQ(endog=endog, k_factors=1, factor_order=1, idiosyncratic_ar1=False)
        return model


# --- Example 1 ---
ex1_name = "_get_small_em_model(); res = mod.fit_em(maxiter=1, tolerance=1e-6, disp=False)"
try:
    modl = _get_small_em_model()
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter('always')
        res = modl.fit_em(maxiter=1, tolerance=1e-6, disp=False)
        probe(ex1_name + '::fit_em_result_type', type(res).__name__)
        _record_basic(ex1_name, res)
        # Capture warning types/messages relevant
        msgs = []
        for wi in w:
            if isinstance(wi.message, (ConvergenceWarning, EstimationWarning)):
                msgs.append((type(wi.message).__name__, str(wi.message)))
        probe(ex1_name + '::warnings', msgs)
except Exception as e:
    probe(ex1_name, '__error__: ' + type(e).__name__ + ': ' + str(e))

# --- Example 2 ---
ex2_name = "_get_small_em_model(); res = mod.fit_em(maxiter=500, tolerance=1e-6, disp=False)"
try:
    modl = _get_small_em_model()
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter('always')
        res = modl.fit_em(maxiter=500, tolerance=1e-6, disp=False)
        probe(ex2_name + '::fit_em_result_type', type(res).__name__)
        _record_basic(ex2_name, res)
        msgs = []
        for wi in w:
            if isinstance(wi.message, (ConvergenceWarning, EstimationWarning)):
                msgs.append((type(wi.message).__name__, str(wi.message)))
        probe(ex2_name + '::warnings', msgs)
except Exception as e:
    probe(ex2_name, '__error__: ' + type(e).__name__ + ': ' + str(e))


# --- Example 3 ---
ex3_name = "_get_small_em_model() with monkeypatched _em_iteration forcing an llf decrease at iteration 2; res = mod.fit_em(maxiter=10, tolerance=1e-10, disp=False)"
try:
    modl = _get_small_em_model()

    # Monkeypatch _em_iteration on the instance/class.
    # We only need to ensure that the second iteration looks like an llf decreased,
    # and that it triggers the internal revert logic.
    orig = getattr(modl, '_em_iteration', None)
    if orig is None:
        raise AttributeError('Model has no _em_iteration')

    call_state = {'i': 0}

    def patched_em_iteration(*args, **kwargs):
        # Increment call counter; assume called once per EM iteration.
        call_state['i'] += 1
        i = call_state['i']
        out = orig(*args, **kwargs)
        # out expected to be (llf, ...) or dict-like; we will try to adjust llf.
        # Ensure llf is a scalar float.
        def as_float(x):
            try:
                return float(np.asarray(x).squeeze())
            except Exception:
                return float(x)

        if isinstance(out, tuple) and len(out) >= 1:
            llf = as_float(out[0])
            # Force a decrease at iteration 2 (i==2)
            if i == 2:
                llf = llf - abs(llf) - 1.0
                out = (llf,) + out[1:]
            return out
        elif isinstance(out, dict):
            if i == 2 and 'llf' in out:
                out['llf'] = as_float(out['llf']) - abs(as_float(out['llf'])) - 1.0
            return out
        else:
            # Unknown structure; if it has attribute/field llf, try common patterns.
            try:
                llf = as_float(getattr(out, 'llf'))
                if i == 2:
                    setattr(out, 'llf', llf - abs(llf) - 1.0)
            except Exception:
                pass
            return out

    setattr(modl, '_em_iteration', patched_em_iteration)

    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter('always')
        res = modl.fit_em(maxiter=10, tolerance=1e-10, disp=False)

        # Record iter and converged flag/error
        try:
            probe(ex3_name + '::mle_retvals_iter', getattr(res.mle_retvals, 'iter', None))
        except Exception as e:
            probe(ex3_name + '::mle_retvals_iter_error', '__error__: ' + type(e).__name__ + ': ' + str(e))
        _record_basic(ex3_name, res)

        msgs = []
        for wi in w:
            if isinstance(wi.message, (ConvergenceWarning, EstimationWarning)):
                msgs.append((type(wi.message).__name__, str(wi.message)))
        probe(ex3_name + '::warnings', msgs)
finally:
    # Best-effort restore
    try:
        if 'modl' in locals() and orig is not None:
            setattr(modl, '_em_iteration', orig)
    except Exception:
        pass

